import os
import sqlite3
from datetime import datetime
from flask import Flask, request, render_template_string, redirect, url_for

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret")

DB_PATH = "db.sqlite3"

# HTML template for the forum interface
INDEX_HTML = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
        .message { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; background: #f9f9f9; }
        .message strong { color: #333; }
        .form-group { margin-bottom: 1rem; }
        input, textarea, button { width: 100%; padding: 0.5rem; margin-top: 0.5rem; box-sizing: border-box; }
        button { background: #28a745; color: white; border: none; cursor: pointer; }
        button:hover { background: #218838; }
        .error { color: red; background: #ffeef0; padding: 0.5rem; border-radius: 4px; margin-bottom: 1rem; display: none; }
        .success { color: green; background: #e6fffa; padding: 0.5rem; border-radius: 4px; margin-bottom: 1rem; display: none; }
    </style>
</head>
<body>
    <h1>MyForum</h1>

    <div class="form-group">
        <input type="text" id="username" placeholder="Username" required>
        <textarea id="content" placeholder="Post a message..." rows="3" required></textarea>
        <button onclick="postMessage()">Post</button>
    </div>

    <div id="messages">
        {% for msg in messages %}
        <div class="message">
            <strong>{{ msg.username }}:</strong> {{ msg.content }}
            <small>{{ msg.timestamp }}</small>
        </div>
        {% endfor %}
    </div>

    <div id="error" class="error"></div>
    <div id="success" class="success"></div>

    <script>
        async function loadMessages() {
            const limit = 50;
            const offset = 0;
            const sort = 'desc';
            const resp = await fetch(`/messages?limit=${limit}&offset=${offset}&sort=${sort}`);
            const data = await resp.text();
            document.getElementById('messages').innerHTML = data;
        }

        async function postMessage() {
            const username = document.getElementById('username').value;
            const content = document.getElementById('content').value;
            if (!username || !content) {
                showError('Please fill in all fields');
                return;
            }
            const resp = await fetch('/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, content })
            });
            const data = await resp.json();
            if (resp.ok) {
                showSuccess('Message posted successfully!');
                document.getElementById('content').value = '';
                loadMessages();
            } else {
                showError(data.detail || 'Failed to post message');
            }
        }

        function showError(msg) {
            document.getElementById('error').textContent = msg;
            document.getElementById('error').style.display = 'block';
        }
        function showSuccess(msg) {
            document.getElementById('success').textContent = msg;
            document.getElementById('success').style.display = 'block';
        }

        // Load messages on page load
        window.onload = loadMessages;
    </script>
</body>
</html>
"""

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        content TEXT NOT NULL,
        timestamp TEXT NOT NULL
    )''')
    conn.commit()
    conn.close()

init_db()

@app.route('/messages', methods=['GET'])
def get_messages():
    limit = int(request.args.get('limit', 10))
    offset = int(request.args.get('offset', 0))
    sort = request.args.get('sort', 'desc').upper()

    if sort not in ('ASC', 'DESC'):
        sort = 'DESC'

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Count total
    c.execute("SELECT COUNT(*) FROM messages")
    total = c.fetchone()[0]

    # Fetch messages with pagination and sorting
    order_dir = "ASC" if sort == "ASC" else "DESC"
    c.execute(
        "SELECT id, username, content, timestamp FROM messages ORDER BY timestamp ? LIMIT ? OFFSET ?",
        (order_dir, limit, offset)
    )
    rows = c.fetchall()
    conn.close()

    messages = []
    for row in rows:
        messages.append({
            'id': row[0],
            'username': row[1],
            'content': row[2],
            'timestamp': row[3]
        })

    return jsonify({'messages': messages, 'total': total}), 200

@app.route('/messages', methods=['POST'])
def post_message():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'detail': 'Invalid input'}), 400

    username = data.get('username')
    content = data.get('content')

    if not username or not content:
        return jsonify({'detail': 'Missing username or content'}), 400

    if not isinstance(username, str) or not isinstance(content, str):
        return jsonify({'detail': 'Invalid input types'}), 400

    timestamp = datetime.utcnow().isoformat()
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute(
        "INSERT INTO messages (username, content, timestamp) VALUES (?, ?, ?)",
        (username, content, timestamp)
    )
    conn.commit()
    conn.close()

    return jsonify({'status': 'success'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
